import{_ as a,o as e,c as i,a5 as s}from"./chunks/framework.CXroN2RO.js";const n="/study/images/data/binary32-layout.svg",r="/study/images/data/float-spacing.svg",b=JSON.parse('{"title":"floatが表せる値と丸め — binary32の表現と刻み幅","description":"","frontmatter":{"title":"floatが表せる値と丸め — binary32の表現と刻み幅","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"data","summary":"binary32の符号・指数・小数部から値を読み、normalとsubnormalの刻み幅、最近接偶数への丸め、0.1fと大きな座標の精度を調べる。C++20の保証とMSVCの実行条件、epsilonとnextafterの役割も区別する。","aliases":["float","floating point","浮動小数点","binary32","IEEE 754","IEC 559","significand","仮数","指数","丸め","最近接偶数","round to nearest ties to even","normal","subnormal","非正規化数","epsilon","nextafter","bit_cast","numeric_limits"],"verification":"一次資料照合（2026-11-03）"}},"headers":[],"relativePath":"data/floating-point-spacing.md","filePath":"data/floating-point-spacing.md"}'),o={name:"data/floating-point-spacing.md"};function l(d,t,p,h,c,g){return e(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="floatが表せる値と丸め-—-binary32の表現と刻み幅" tabindex="-1">floatが表せる値と丸め — binary32の表現と刻み幅 <a class="header-anchor" href="#floatが表せる値と丸め-—-binary32の表現と刻み幅" aria-label="Permalink to &quot;floatが表せる値と丸め — binary32の表現と刻み幅&quot;">​</a></h1><p>浮動小数点数で表せる値は離れた点として並び、その間の値は丸めて表します。binary32のnormalでは、絶対値の桁が上がると点の間隔が広くなります。ゲームの座標や時間を読むときも、値の範囲とその周辺の刻み幅を分けて考えます。</p><p>ここではC++20を主対象に、IEEE 754の32bit形式である<strong>binary32</strong>を説明します。C++の型名<code>float</code>だけから、必ずこの形式であるとは決まりません。<a href="https://timsong-cpp.github.io/cppwp/n4861/basic.fundamental" target="_blank" rel="noreferrer">公開C++20草案N4861: basic.fundamental</a></p><h2 id="floatという型と、観察する環境" tabindex="-1">floatという型と、観察する環境 <a class="header-anchor" href="#floatという型と、観察する環境" aria-label="Permalink to &quot;floatという型と、観察する環境&quot;">​</a></h2><p>具体例は**通常のMSVC・Windows x64の<code>float</code>**です。MSVCは<code>float</code>に4byteのIEEE単精度形式を使います。これをC++規格の全処理系に対する保証とは分けます。<a href="https://learn.microsoft.com/en-us/cpp/build/ieee-floating-point-representation?view=msvc-170" target="_blank" rel="noreferrer">Microsoft: IEEE Floating-Point Representation</a></p><p>別環境で同じビットの図を使う前に、次の性質を確認します。<code>std::numeric_limits&lt;float&gt;</code>は<code>&lt;limits&gt;</code>で調べる型の性質です。</p><table tabindex="0"><thead><tr><th>確認するもの</th><th>今回の具体例の前提</th><th>読み方</th></tr></thead><tbody><tr><td><code>CHAR_BIT</code>と<code>sizeof(float)</code></td><td>8、4</td><td>1byte＝8bitで、格納全体は32bit</td></tr><tr><td><code>is_iec559</code></td><td><code>true</code></td><td>IEC 60559／IEEE 754に従う型であることの指標</td></tr><tr><td><code>radix</code></td><td>2</td><td>基数が2</td></tr><tr><td><code>digits</code></td><td>24</td><td>normalの有効桁数が2進24桁</td></tr><tr><td><code>min_exponent</code></td><td>−125</td><td>最小normalは2の「この値−1」乗</td></tr><tr><td><code>max_exponent</code></td><td>128</td><td>最大のnormalの指数に1を加えた値</td></tr></tbody></table><p><strong>最小normalの指数−126と、<code>min_exponent</code>の−125は同じ数値ではありません。</strong> メンバーの定義に1の差があります。また、<code>is_iec559</code>だけを確認して、任意の処理系のビット配置やコンパイラの最適化条件まで同一と判断するものではありません。<a href="https://timsong-cpp.github.io/cppwp/n4861/numeric.limits.members" target="_blank" rel="noreferrer">N4861: numeric.limits.members</a></p><p>以下の演算結果は、特に断らない限り、binary32へ<strong>最近接偶数</strong>で丸め、subnormalを保持する条件で読みます。実行時の丸めモードやMSVCの<code>/fp</code>設定は、型の格納形式とは別に確認します。</p><h2 id="binary32の三つのフィールド" tabindex="-1">binary32の三つのフィールド <a class="header-anchor" href="#binary32の三つのフィールド" aria-label="Permalink to &quot;binary32の三つのフィールド&quot;">​</a></h2><p>binary32は、符号1bit、格納された指数8bit、小数部23bitからなります。ここでは符号をS、指数フィールドを整数として読んだ値をE、小数部フィールドを整数として読んだ値をFとします。上位ビットから説明しており、アドレス順のバイト列とは別です。</p><p>**normal（正規化数）**の範囲では、値は次の式になります。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>値 = (−1)^S × (1 + F / 2^23) × 2^(E − 127)</span></span>
<span class="line"><span>条件: 1 ≦ E ≦ 254、0 ≦ F &lt; 2^23</span></span></code></pre></div><p>指数に127を足して格納する仕組みを<strong>バイアス</strong>と呼びます。<code>1 + F / 2^23</code>は、2進数では<code>1.xxxxx…</code>の形です。先頭の1は格納を省略できるので、<strong>小数部23bitと、隠れた1bitを合わせて有効桁は24bit</strong>になります。この隠れた1はnormalの規則です。<a href="https://learn.microsoft.com/en-us/cpp/build/ieee-floating-point-representation?view=msvc-170" target="_blank" rel="noreferrer">Microsoft: IEEE Floating-Point Representation</a></p><p>例えば1.5は、2進で<code>1.1 × 2^0</code>です。S＝0、E＝127、F＝2²²となり、この環境の32bit表現を16進で書くと<code>0x3FC00000</code>です。Fは小数そのものを格納した整数ではなく、<code>2^23</code>で割って小数部として読むフィールドです。</p><figure class="study-figure"><img src="`+n+`" alt="binary32を符号1bit、指数8bit、小数部23bitに分け、1.5の表現0x3FC00000を読む図。normalには隠れた1があり、指数フィールドが0または255のときは別の規則になる。" width="760" height="1410"><figcaption><strong>格納する小数部は23bit、normalの精度は24bit。</strong> ビットの役割の図であり、メモリのバイト順を示すものではありません。<a href="/study/images/data/binary32-layout.svg" target="_blank" rel="noopener noreferrer">binary32の構成図を拡大</a></figcaption></figure><h3 id="e-0とe-255は別に読む" tabindex="-1">E＝0とE＝255は別に読む <a class="header-anchor" href="#e-0とe-255は別に読む" aria-label="Permalink to &quot;E＝0とE＝255は別に読む&quot;">​</a></h3><table tabindex="0"><thead><tr><th>E</th><th>F</th><th>分類</th></tr></thead><tbody><tr><td>1〜254</td><td>任意</td><td>normal</td></tr><tr><td>0</td><td>0以外</td><td>subnormal：隠れた1を使わないゼロ付近の数</td></tr><tr><td>0</td><td>0</td><td>Sに応じた＋0または−0</td></tr><tr><td>255</td><td>0</td><td>Sに応じた＋∞または−∞</td></tr><tr><td>255</td><td>0以外</td><td>NaN：数ではない値を表す分類</td></tr></tbody></table><p>**subnormal（非正規化数）**では<code>1.F</code>ではなく<code>0.F</code>として読みます。∞やNaNを、非常に大きい通常の有限値として同じ式へ入れることもできません。ここでは分類までを扱い、例外やNaNの詳細な種類は別テーマとします。<a href="https://docs.oracle.com/cd/E19957-01/806-3568/ncg_math.html" target="_blank" rel="noreferrer">Oracle Numerical Computation Guide: Single Format</a></p><h2 id="表現するときと、演算するときの丸め" tabindex="-1">表現するときと、演算するときの丸め <a class="header-anchor" href="#表現するときと、演算するときの丸め" aria-label="Permalink to &quot;表現するときと、演算するときの丸め&quot;">​</a></h2><p>10進数の0.1は、数学では正確な1/10です。しかし2進では小数部が循環し、有限の桁で書き切れません。したがってbinary32のどの値とも完全には一致しません。<a href="https://docs.oracle.com/cd/E19957-01/806-3568/ncg_goldberg.html" target="_blank" rel="noreferrer">Oracle: Floating-point Formats</a></p><p>今回のMSVC環境で<code>0.1f</code>を表すと、ビット表現は<code>0x3DCCCCCD</code>、その値を正確に10進で書くと次になります。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>数学上の値:       0.1</span></span>
<span class="line"><span>binary32の近似値: 0.100000001490116119384765625</span></span></code></pre></div><p>これはまず<strong>値を表す段階での近似</strong>です。表示桁数が少ないと<code>0.1</code>と表示されても、保存した値が数学上の1/10になったわけではありません。<code>f</code>付きリテラルは<code>float</code>、付かない<code>0.1</code>は<code>double</code>です。C++20自体にはリテラルの変換について実装定義の選択があるので、このビット列は対象環境で確かめる具体例として、一般規格の保証と区別します。<a href="https://timsong-cpp.github.io/cppwp/n4861/lex.fcon" target="_blank" rel="noreferrer">N4861: lex.fcon</a></p><p>さらに、表せる値同士を計算しても、その数学的な結果が表せるとは限りません。その場合には<strong>演算結果を格納する段階でも丸め</strong>が必要になります。入力の近似と、演算に伴う丸めは別の出来事です。「小数を一度読み込んだときだけ誤差が入る」とは考えません。<a href="https://docs.oracle.com/cd/E19957-01/806-3568/ncg_goldberg.html" target="_blank" rel="noreferrer">Oracle: Rounding Error</a></p><h3 id="最近接偶数とは" tabindex="-1">最近接偶数とは <a class="header-anchor" href="#最近接偶数とは" aria-label="Permalink to &quot;最近接偶数とは&quot;">​</a></h3><p>最近接丸めでは、表せる隣の値のうち近い方を選びます。ちょうど中間なら、<strong>保持する有効桁の最下位bitが0になる方</strong>を選ぶのが最近接偶数です。「10進表示の末尾が偶数」という規則ではありません。MSVCの<code>FE_TONEAREST</code>は、この中間値の扱いを持ちます。<a href="https://learn.microsoft.com/en-us/cpp/c-runtime-library/reference/fegetround-fesetround2?view=msvc-170" target="_blank" rel="noreferrer">Microsoft: fegetround / fesetround</a></p><h2 id="normalの刻み幅は指数で変わる" tabindex="-1">normalの刻み幅は指数で変わる <a class="header-anchor" href="#normalの刻み幅は指数で変わる" aria-label="Permalink to &quot;normalの刻み幅は指数で変わる&quot;">​</a></h2><p>正のnormalで、値が**[2ᵉ, 2ᵉ⁺¹)<strong>にあるとき、次の大きい有限値との間隔は、最大有限値を除いて</strong>2ᵉ⁻²³**です。角括弧は左端を含み、丸括弧は右端を含まないことを示します。ここでのeは、格納フィールドEから127を引いた実際の指数です。</p><p>この間隔はnormalの式から求まります。Fを1増やすと小数部が<code>1 / 2^23</code>増え、それに<code>2^e</code>を掛けるためです。区間内の点は等間隔で、区間を一つ上がると間隔が2倍になります。</p><table tabindex="0"><thead><tr><th>正の値の周辺</th><th style="text-align:right;">e</th><th style="text-align:right;">大きい側の隣までの間隔</th></tr></thead><tbody><tr><td>1</td><td style="text-align:right;">0</td><td style="text-align:right;">2⁻²³ ≈ 0.00000011920928955</td></tr><tr><td>100,000</td><td style="text-align:right;">16</td><td style="text-align:right;">2⁻⁷ ＝ 0.0078125</td></tr><tr><td>1,048,576（2²⁰）</td><td style="text-align:right;">20</td><td style="text-align:right;">2⁻³ ＝ 0.125</td></tr><tr><td>8,388,608（2²³）</td><td style="text-align:right;">23</td><td style="text-align:right;">1</td></tr><tr><td>16,777,216（2²⁴）</td><td style="text-align:right;">24</td><td style="text-align:right;">2</td></tr></tbody></table><p><strong>2の整数乗ちょうどの点では、前後の間隔が異なります。</strong> 1の小さい側の隣までは2⁻²⁴、大きい側は2⁻²³です。2²⁴では小さい側が1、大きい側が2になります。ただし最小normalの境界では、下側がsubnormalなので、この「下側は半分」という説明を適用しません。</p><figure class="study-figure"><img src="`+r+`" alt="1付近、100000付近、2の24乗付近で、binary32の表せる値の間隔を比較する図。1と2の24乗では前後の間隔が異なり、16777217は表せる二つの値の中間で最近接偶数により16777216へ丸められる。段ごとに縮尺は異なる。" width="760" height="1470"><figcaption><strong>有効桁数が一定でも、値の単位で測った刻み幅は一定ではない。</strong> 各段の縮尺は別です。図の「前」「後」は値の大小であり、メモリの並びではありません。<a href="/study/images/data/float-spacing.svg" target="_blank" rel="noopener noreferrer">刻み幅の図を拡大</a></figcaption></figure><h3 id="subnormalの間隔は一定" tabindex="-1">subnormalの間隔は一定 <a class="header-anchor" href="#subnormalの間隔は一定" aria-label="Permalink to &quot;subnormalの間隔は一定&quot;">​</a></h3><p>subnormalの正の値は、<code>F × 2^-149</code>です。最小の正の値は2⁻¹⁴⁹、隣との間隔も2⁻¹⁴⁹で一定になります。最小normalの2⁻¹²⁶との境界も同じ間隔でつながります。<strong>ゼロへ近づくほど、いつまでも値に比例して細かくなる仕組みではありません。</strong> 隠れた1を使わない領域では、有効な桁数もnormalの24bitと同じには保てません。<a href="https://docs.oracle.com/cd/E19957-01/806-3568/ncg_math.html" target="_blank" rel="noreferrer">Oracle: Single Format / Subnormal Numbers</a></p><p><code>numeric_limits&lt;float&gt;::min()</code>は、subnormalがある浮動小数点型では最小の正のnormalです。最小の正のsubnormalを調べる<code>denorm_min()</code>、最も負の有限値を調べる<code>lowest()</code>と区別します。<a href="https://learn.microsoft.com/en-us/cpp/standard-library/numeric-limits-class?view=msvc-170" target="_blank" rel="noreferrer">Microsoft: numeric_limits</a></p><h2 id="_224-1が224へ丸められる理由" tabindex="-1">2²⁴＋1が2²⁴へ丸められる理由 <a class="header-anchor" href="#_224-1が224へ丸められる理由" aria-label="Permalink to &quot;2²⁴＋1が2²⁴へ丸められる理由&quot;">​</a></h2><p>2²⁴の直後には2刻みで点が並ぶので、数学上の16,777,217は表せません。表せる16,777,216と16,777,218の<strong>ちょうど中間</strong>です。最近接偶数では、最下位bitが0の16,777,216側を選びます。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>表せる値:  16,777,216       16,777,218</span></span>
<span class="line"><span>                    ↑</span></span>
<span class="line"><span>数学上の結果:   16,777,217</span></span>
<span class="line"><span>binary32へ最近接偶数で丸める結果: 16,777,216</span></span></code></pre></div><p>2²⁴と1はそれぞれ正確に表せるので、この例は「入力が10進小数だから」起きる現象ではありません。正確な二つの入力からでも、結果を保存するときに1が失われます。一方、16,777,218は表せるので、「2²⁴を超えた整数はすべて表せない」という意味でもありません。</p><h2 id="nextafterとepsilonが示すもの" tabindex="-1">nextafterとepsilonが示すもの <a class="header-anchor" href="#nextafterとepsilonが示すもの" aria-label="Permalink to &quot;nextafterとepsilonが示すもの&quot;">​</a></h2><p><code>&lt;cmath&gt;</code>の<code>std::nextafter</code>は、指定した方向にある<strong>次の表現可能な値</strong>を返します。<code>float</code>の隣を調べるなら、両引数を<code>float</code>にそろえます。次は<code>&lt;cmath&gt;</code>と<code>&lt;limits&gt;</code>を使う関数内の例です。<a href="https://learn.microsoft.com/en-us/cpp/c-runtime-library/reference/nextafter-functions?view=msvc-170" target="_blank" rel="noreferrer">Microsoft: nextafter functions</a></p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100000.0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> next </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nextafter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(x, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">numeric_limits</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">infinity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> gap </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> next </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // このbinary32環境では0.0078125f = 1/128</span></span></code></pre></div><p><code>std::numeric_limits&lt;float&gt;::epsilon()</code>は、<strong>1と、1より大きい最小の表現可能値との差</strong>です。binary32では2⁻²³です。全範囲で隣の値までの距離がこの値になるわけではなく、あらゆる比較にそのまま使える許容誤差でもありません。<a href="https://timsong-cpp.github.io/cppwp/n4861/numeric.limits.members#25" target="_blank" rel="noreferrer">N4861: numeric.limits.members — epsilon</a></p><p>ゲームの座標なら、刻み幅をゲーム内の単位に読み替えます。例えば1unit＝1mなら、100,000付近の刻みは約7.8mm、2²⁴付近の大きい側は2mです。後者では座標に1mを加えようとしても、丸めた結果が同じ座標になり得ます。必要な最小の変化、座標の大きさ、単位の定義を合わせて評価します。</p><p>表せる値の間隔と、用途上どこまでの差を許すかは別の問いです。<a href="/study/math/floating-point-comparison.html">浮動小数点の比較設計</a>では、<code>==</code>による一致と近似一致の目的を分け、絶対許容差・相対許容差、値域と単位、NaNや無限大の扱いを調べます。<a href="/study/practice/math/float-comparison-observation.html">比較の観察例</a>で、選んだ許容差によって判定がどう変わるかを確認できます。型の<code>epsilon()</code>をそのまま万能な許容差とする手順ではありません。</p><h2 id="bit-castは表現を読む操作" tabindex="-1">bit_castは表現を読む操作 <a class="header-anchor" href="#bit-castは表現を読む操作" aria-label="Permalink to &quot;bit_castは表現を読む操作&quot;">​</a></h2><p>C++20の<code>std::bit_cast</code>は、同じ大きさのtrivially copyableな型（バイト列のコピーで値を移せる種類の型）の間で、ビット表現に対応する値を作ります。次は<code>&lt;bit&gt;</code>と<code>&lt;cstdint&gt;</code>を使い、上記のMSVC x64の配置と、<code>uint32_t</code>が利用可能であることを確認した環境の例です。</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">constexpr</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> auto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bits </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bit_cast</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.5</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 0x3FC00000</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">constexpr</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> auto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> number </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> static_cast&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint32_t&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.5</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 数値変換なので1</span></span></code></pre></div><p>前者は浮動小数点のフィールドを読むため、後者は数値を整数へ変換するための操作です。元の変数の型を変えたり、バイト順を交換したりする機能ではありません。同じ大きさという条件などは<code>bit_cast</code>の契約で、<code>float</code>が4byteという推測だけで満たしたことにはしません。<a href="https://timsong-cpp.github.io/cppwp/n4861/bit.cast" target="_blank" rel="noreferrer">N4861: bit.cast</a></p><h2 id="観察時の丸めとコンパイラ設定" tabindex="-1">観察時の丸めとコンパイラ設定 <a class="header-anchor" href="#観察時の丸めとコンパイラ設定" aria-label="Permalink to &quot;観察時の丸めとコンパイラ設定&quot;">​</a></h2><p>型の性質がbinary32でも、式の途中の精度や丸めの扱いは、コンパイラと実行条件も確認します。MSVCで実行時の浮動小数点環境を読み書きする観察には<code>/fp:strict</code>を使います。<code>/fp:fast</code>には演算の並べ替えや丸めの省略を許す最適化があり、同じ実験条件として扱いません。<code>/fp:strict</code>でも中間計算が常に保存先の型と同じ精度になる、という説明はしません。<a href="https://learn.microsoft.com/en-us/cpp/build/reference/fp-specify-floating-point-behavior?view=msvc-170" target="_blank" rel="noreferrer">Microsoft: /fp</a></p><p><code>std::fesetround(FE_TONEAREST)</code>の成功と、<code>std::fegetround()</code>の結果を確認し、実行時の計算結果を<code>float</code>へ保存して観察します。実行時に設定した丸めモードが、翻訳時のリテラル変換や定数式まで変更するわけではありません。<a href="https://learn.microsoft.com/en-us/cpp/c-runtime-library/reference/fegetround-fesetround2?view=msvc-170" target="_blank" rel="noreferrer">Microsoft: fegetround / fesetround</a></p><p>C#、Unity、GPUの結果へ広げるときも、実行基盤と精度の設定を確認します。単に型名が同じだから、この実験の結果がそのまま一致するとは判断しません。</p><p><a href="/study/practice/data/float-spacing-observation.html">C++でfloatの刻み幅と丸めを観察する</a>では、型の性質、0.1fの表現、隣の値、2²⁴の中間値を確認します。ビット・16進数・バイト順の土台は<a href="/study/data/integer-bits-and-bytes.html">整数をビット列・16進数・バイト列で読む</a>、分野全体の案内は<a href="/study/guide/low-level/computer-and-data.html">情報表現の学習ガイド</a>を参照してください。</p>`,55)])])}const m=a(o,[["render",l]]);export{b as __pageData,m as default};
